public class Car {
    String make;
    int year;

    // No-arg constructor
    Car() {
        make = "Unknown";
        year = 2024;
    }

    // Parameterized constructor
    Car(String make, int year) {
        this.make = make;
        this.year = year;
    }
}

Car c1 = new Car();             // uses no-arg
Car c2 = new Car("Toyota", 2025); // uses parameterized
